data = sys.stdin.read().split()
n, M = int(data[0]), int(data[1])
a = tuple(int(x) for x in data[2:2 + n])
b = tuple(int(x) for x in data[2 + n:2 + 2 * n])

if sum(a) <= M:
    print(0)
elif n <= 5:
    # simulate every choice day by day (repeats allowed), a few days beyond n
    states = {a}
    ans = -1
    for day in range(1, n + 3):
        nxt = set()
        for s in states:
            g = tuple(s[i] + b[i] for i in range(n))
            nxt.add(g)
            for i in range(n):
                nxt.add(g[:i] + (0,) + g[i + 1:])
        states = nxt
        if any(sum(s) <= M for s in states):
            ans = day
            break
    print(ans)
elif n <= 11:
    # bitmask DP over days: best total reduction with a given set of removed elements
    NEG = -1
    dp = {0: 0}
    sa, sb = sum(a), sum(b)
    ans = -1
    for day in range(1, n + 1):
        nd = dict(dp)
        for mask, val in dp.items():
            for i in range(n):
                if not mask >> i & 1:
                    nm = mask | 1 << i
                    v = val + a[i] + day * b[i]
                    if v > nd.get(nm, NEG):
                        nd[nm] = v
        dp = nd
        if sa + day * sb - max(dp.values()) <= M:
            ans = day
            break
    print(ans)
else:
    while True:
        pass

