def gen(rng):
    def fmt(M, a, b):
        return f"{len(a)} {M}\n" + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, b))
    def best(a, b):
        n = len(a)
        NEG = -10 ** 18
        dp = [0] + [NEG] * n
        for i in sorted(range(n), key=lambda i: b[i]):
            for j in range(n, 0, -1):
                if dp[j - 1] > NEG:
                    dp[j] = max(dp[j], dp[j - 1] + a[i] + j * b[i])
        return [sum(a) + t * sum(b) - dp[t] for t in range(n + 1)]
    tests = [
        fmt(1, [10, 15], [3, 2]),
        fmt(33, [7, 3, 5, 6, 8, 0, 8], [2, 4, 1, 1, 2, 3, 1]),
        fmt(92, [35, 58, 39], [30, 20, 10]),
        fmt(905, [170, 203, 171, 42, 60, 111, 152], [60, 32, 63, 65, 70, 50, 63]),
        fmt(5, [0], [0]),
        fmt(1, [0], [0]),
        fmt(10, [5], [4]),
        fmt(6, [5], [4]),
        fmt(1000, [0, 0, 0], [0, 0, 0]),
        fmt(15, [1, 2, 3, 4, 5], [2, 1, 6, 7, 8]),
    ]
    def rnd(n, hi_a, hi_b):
        a = [rng.randint(0, hi_a) for _ in range(n)]
        b = [rng.randint(0, hi_b) for _ in range(n)]
        v = best(a, b)
        mode = rng.randint(0, 3)
        if mode == 0:
            M = v[rng.randint(0, n)]          # reachable on that day (or earlier), exact boundary
        elif mode == 1:
            M = min(v) + rng.randint(-2, 0)   # at or just below the best possible
        elif mode == 2:
            M = v[rng.randint(0, n)] - 1      # that day just fails
        else:
            M = rng.randint(1, max(2, sum(a) + 5))
        return fmt(max(1, M), a, b)
    for n in (1, 2, 3, 3, 4, 4, 4, 5, 5):
        for _ in range(2):
            tests.append(rnd(n, rng.choice([5, 20]), rng.choice([5, 20])))
    for n in (6, 8, 10, 11):
        tests.append(rnd(n, 30, 10))
    for _ in range(3):
        tests.append(rnd(rng.randint(12, 19), 10000, 10000))
    tests.append(rnd(19, 10000, 10000))
    tests.append(rnd(19, 10000, 100))
    tests.append(rnd(19, 100, 10000))
    return tests

